"""
AI 百人導師團隊公開介紹頁。跑法：python app.py（預設 port 5062，獨立Cloudflare通道對外開）
訪客點「我要加入百人導師計劃」→ /apply 填姓名/公司/LINE ID → 送出後直接通知教練LINE(sme-register-fn)，
教練親自加對方LINE後再手動請對方填完整資料（不再有公開自助全欄位表單+馬上上架的舊流程）
舊自助表單/join(GET+POST)已關閉並轉址到/apply；既有導師自己修改/刪除資料的/join/edit/<token>不受影響
教練看名單/補種子資料/修正錯誤 → /admin（帳密登入，見 /admin/login）
"""
import os
import re
import secrets
import time
from collections import defaultdict
from io import BytesIO

import requests
from flask import Flask, abort, redirect, render_template, request, session, url_for
from werkzeug.security import check_password_hash
from PIL import Image, ImageOps, UnidentifiedImageError

import db

app = Flask(__name__)
app.secret_key = os.environ.get("MENTOR100_SECRET_KEY", "")
ADMIN_USER = os.environ.get("MENTOR100_ADMIN_USER", "")
ADMIN_PASSWORD_HASH = os.environ.get("MENTOR100_ADMIN_PASSWORD_HASH", "")

UPLOAD_DIR = os.path.join(os.path.dirname(__file__), "static", "uploads")
ALLOWED_EXTS = {"jpg", "jpeg", "png", "webp"}
MAX_PHOTO_EDGE = 1200
DRAFT_PLACEHOLDER_PHOTO = "_placeholder.jpg"  # 產生填寫連結時的預設照片，申請人上傳後會被換掉
app.config["MAX_CONTENT_LENGTH"] = 8 * 1024 * 1024  # 8MB

TRACKING_START = "2026-08-08 00:00:00"  # 首頁「到訪次數」計數起算點，教練指定

SME_REGISTER_API = "https://sme-register-fn.netlify.app/.netlify/functions/register"

_rate_limit_log: dict[str, list[float]] = defaultdict(list)
RATE_LIMIT_MAX = 5
RATE_LIMIT_WINDOW = 3600  # 1 小時


def _sanitize_filename(raw: str) -> str:
    """保留中文檔名，只擋掉路徑穿越與危險字元。
    不能直接用werkzeug的secure_filename——它會把中文整段砍掉。"""
    name = os.path.basename(raw).replace("\x00", "")
    name = re.sub(r'[/\\:*?"<>|]', "", name)
    return name.strip() or "file"


def _process_and_save_photo(file_storage) -> str | None:
    """驗證是不是真的圖片、轉正方向、縮圖存檔。回傳存檔後的檔名；失敗回傳 None。
    近百位導師各自上傳，檔名很容易撞名（例如都叫IMG_1234.JPG），
    所以消毒後一律加隨機後綴，不會互相覆蓋。"""
    raw_name = _sanitize_filename(file_storage.filename or "photo.jpg")
    ext = raw_name.rsplit(".", 1)[-1].lower() if "." in raw_name else ""
    if ext not in ALLOWED_EXTS:
        ext = "jpg"

    try:
        data = file_storage.read()
        img = Image.open(BytesIO(data))
        img.verify()
        img = Image.open(BytesIO(data))  # verify() 後要重新開才能再讀
        img = ImageOps.exif_transpose(img)
        if img.mode not in ("RGB", "L"):
            img = img.convert("RGB")
    except (UnidentifiedImageError, OSError):
        return None

    img.thumbnail((MAX_PHOTO_EDGE, MAX_PHOTO_EDGE))

    stem = raw_name.rsplit(".", 1)[0] if "." in raw_name else raw_name
    filename = f"{stem}-{secrets.token_hex(4)}.jpg"
    os.makedirs(UPLOAD_DIR, exist_ok=True)
    img.save(os.path.join(UPLOAD_DIR, filename), "JPEG", quality=85)
    return filename


def _check_rate_limit(ip: str) -> bool:
    """回傳 True 代表可以送出，False 代表這個IP這小時已經送太多次。"""
    now = time.time()
    log = _rate_limit_log[ip]
    log[:] = [t for t in log if now - t < RATE_LIMIT_WINDOW]
    if len(log) >= RATE_LIMIT_MAX:
        return False
    log.append(now)
    return True


def _extract_links(form) -> dict:
    cols = (*db.LINK_COLUMNS, *db.LABEL_COLUMNS)
    return {col: (form.get(col) or "").strip() for col in cols}


def _client_ip() -> str:
    """站台走Cloudflare Tunnel，真實訪客IP在CF-Connecting-IP，其次才是X-Forwarded-For。"""
    return (
        request.headers.get("CF-Connecting-IP")
        or (request.headers.get("X-Forwarded-For") or "").split(",")[0].strip()
        or request.remote_addr
        or "unknown"
    )


@app.route("/")
def index():
    conn = db.get_conn()
    db.log_visit(conn, _client_ip())
    mentors = [{**dict(m), "links": db.mentor_links(m)} for m in db.list_mentors_published(conn)]
    total_views = db.get_total_views_since(conn, TRACKING_START)
    conn.close()
    return render_template("index.html", mentors=mentors, total_views=total_views)


@app.route("/api/mentor-click/<int:mentor_id>", methods=["POST"])
def api_mentor_click(mentor_id):
    conn = db.get_conn()
    ok = db.log_mentor_click(conn, mentor_id)
    conn.close()
    return ("", 204) if ok else ("", 404)


@app.route("/join", methods=["GET", "POST"])
def join_closed():
    """舊的公開自助全欄位表單已關閉(教練2026-08-08裁示改人工申請)，一律轉去新的/apply。"""
    return redirect(url_for("apply_form"))


def _notify_coach_line(session_label: str, name: str, company: str = "", phone: str = "") -> None:
    """送到sme-register-fn，教練LINE會收到通知。失敗不影響使用者流程(best-effort)。"""
    try:
        requests.post(
            SME_REGISTER_API,
            json={"session": session_label, "name": name, "company": company, "phone": phone, "email": ""},
            timeout=5,
        )
    except requests.RequestException:
        pass


@app.route("/apply", methods=["GET"])
def apply_form():
    return render_template("apply.html", error=None, form={})


@app.route("/apply", methods=["POST"])
def apply_submit():
    # honeypot：一般人看不到這個欄位，機器人才會填
    if (request.form.get("website") or "").strip():
        return redirect(url_for("apply_thanks"))

    ip = _client_ip()
    if not _check_rate_limit(ip):
        return render_template(
            "apply.html", error="這個小時送出次數太多了，請稍後再試一次", form=request.form
        ), 429

    name = (request.form.get("name") or "").strip()
    company = (request.form.get("company") or "").strip()
    line_id = (request.form.get("line_id") or "").strip()

    error = None
    if not name:
        error = "請填寫姓名"
    elif not company:
        error = "請填寫公司/職稱"
    elif not line_id:
        error = "請填寫您的 LINE ID，教練才能加您好友"

    if error:
        return render_template(
            "apply.html", error=error, form=request.form
        ), 400

    conn = db.get_conn()
    db.insert_application(conn, name, company, line_id)
    conn.close()
    _notify_coach_line("【百人導師申請】", name, company, line_id)

    return redirect(url_for("apply_thanks"))


@app.route("/apply/thanks")
def apply_thanks():
    return render_template("apply_thanks.html")


@app.route("/join/thanks")
def join_thanks():
    token = request.args.get("token") or ""
    edit_url = url_for("join_edit", token=token, _external=True) if token else None
    return render_template("join_thanks.html", edit_url=edit_url)


@app.route("/join/edit/<token>", methods=["GET"])
def join_edit(token):
    conn = db.get_conn()
    mentor = db.get_mentor_by_token(conn, token)
    conn.close()
    if not mentor:

def _lottery_greet_url(name: str, event_name: str) -> str:
    """組出「加好友同時帶問候語」的LINE連結：對方點開LINE就看到預填好的訊息，
    按下傳送才算完成binding+登記抽獎（webhook比對這句話裡的姓名寫入line_user_id）。"""
    greet_text = (
        f"我是{name}，剛報名了{event_name}。"
        f"我要現場立即參加抽獎（送出才算登記成功）"
    )
    return f"https://line.me/R/oaMessage/{LINE_OA_ID}/?{quote(greet_text)}"

GREET_PATTERN = re.compile(r"^我是(.+?)，剛報名了")

SLIDES_DIR = os.path.join(os.path.dirname(__file__), "slides")
OPENCLAW_CONFIG_PATH = os.path.expanduser("~/.openclaw/openclaw.json")
TELEGRAM_NOTIFY_CHAT_ID = "6124913915"  # 教練跟小龍蝦的對話，路徑大全.md已記錄
TELEGRAM_REGISTRATION_GROUP_CHAT_ID = "-5349981085"  # 教練2026-08-24建立「活動報名即時通知」群組，教練+佩佩老師+bot三方共見


NOTIFY_FAIL_LOG = os.path.join(os.path.dirname(__file__), "notify_failures.log")


def _notify_xiaolongxia(text: str, chat_id: str = TELEGRAM_NOTIFY_CHAT_ID) -> bool:
    """發Telegram訊息，預設給教練個人對話；報名通知改傳group chat_id同時通知佩佩老師。

    失敗不影響網頁本身回應，但 🔴 一定要留下痕跡——
    2026-08-17~08-23 教練整整一週收不到報名通知，就是因為舊版 LINE 通知函式
    用 `except: pass` 把 HTTP 429（月配額用完）整個吞掉，沒有任何 log、沒有任何人知道，
    教練還以為報名系統壞了（試金石案例62）。從此：靜默失敗一律不准，至少寫一行。
    """
    try:
        with open(OPENCLAW_CONFIG_PATH, encoding="utf-8") as f:
            config = json.load(f)
        bot_token = config["channels"]["telegram"]["accounts"]["bot_main"]["botToken"]
        body = json.dumps({"chat_id": chat_id, "text": text}).encode("utf-8")
        req = urllib.request.Request(
            f"https://api.telegram.org/bot{bot_token}/sendMessage",
            data=body, method="POST", headers={"Content-Type": "application/json"},
        )
        with urllib.request.urlopen(req, timeout=10) as resp:
            result = json.loads(resp.read().decode("utf-8"))
        if not result.get("ok"):
            _log_notify_failure(chat_id, f"telegram回傳ok=false: {result}", text)
            return False
        return True
    except Exception as e:
        _log_notify_failure(chat_id, repr(e), text)
        return False


def _log_notify_failure(chat_id: str, reason: str, original_text: str) -> None:
    """通知送不出去時，把「誰、什麼時候、為什麼、原本要送什麼」寫進檔案，事後查得到。"""
    try:
        stamp = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        with open(NOTIFY_FAIL_LOG, "a", encoding="utf-8") as f:
            f.write(f"[{stamp}] chat_id={chat_id} 失敗原因={reason}\n"
                    f"    原訊息：{original_text[:300].replace(chr(10), ' / ')}\n")
    except Exception:
        pass  # 連寫 log 都失敗就真的沒辦法了，但至少不能讓網頁掛掉


@app.route("/")
def root():
    return redirect("https://coach1973.github.io/ai-talk/")


QR_DIR = os.path.join(os.path.dirname(__file__), "qr")


@app.route("/qr/<path:filename>")
def qr_file(filename):
    return send_from_directory(QR_DIR, filename)


@app.route("/checkin", methods=["GET"])
def checkin():
    """固定不變的報到入口，QR立牌永久印這個網址。後台切哪場是「目前活動」，
    這裡就自動導去那場的簽到頁，不用重印立牌。
    2026-07-28教練指出來賓線上報名時已留過姓名/電話，現場只需要再輸入手機號碼比對身份即可，
    不用整份表單重填一次——比對成功才算「簽到」，一樣會記進signups表供集點使用。"""
    conn = db.get_conn()
    event = db.get_current_event(conn)
    conn.close()
    if not event:
        return "目前沒有進行中的活動，請稍後再試", 404
    return render_template("checkin.html", event=event, error=None, phone="")


@app.route("/checkin", methods=["POST"])
def checkin_submit():
    conn = db.get_conn()
    event = db.get_current_event(conn)
    if not event:
        conn.close()
        return "目前沒有進行中的活動，請稍後再試", 404

