31	<style>
32	:root{
33	--bg:#f6f1e8;
34	--bg-soft:#fffdf9;
35	--paper:rgba(255,255,255,.84);
36	--text:#241f1a;
37	--muted:#5b5148;
38	--muted-2:#7d6d5c;
39	--line:#dfcfbb;
40	--accent:#9b5b3f;
41	--accent-2:#c8845b;
42	--gold:#b9956b;
43	--olive:#2f3a35;
44	--olive-2:#435248;
45	--max:1180px;
46	--shadow:0 20px 60px rgba(89,67,46,.10);
47	}
48	*{box-sizing:border-box}
49	html{scroll-behavior:smooth}
50	body{margin:0;font-family:"Noto Sans TC","PingFang TC","Microsoft JhengHei",sans-serif;background:var(--bg);color:var(--text);line-height:1.7}
51	a{text-decoration:none;color:inherit}
52	img{max-width:100%;display:block}
53	.container{width:min(var(--max),calc(100% - 32px));margin:auto}
54	.section{padding:88px 0}
55	.eyebrow{font-size:12px;letter-spacing:.24em;text-transform:uppercase;font-weight:900;color:#8a6844}
56	.hero{position:relative;overflow:hidden;padding:82px 0 88px;background:
57	radial-gradient(circle at 15% 20%, rgba(255,255,255,.52), transparent 20%),
58	radial-gradient(circle at 80% 12%, rgba(200,132,91,.18), transparent 22%),
59	radial-gradient(circle at 68% 78%, rgba(67,82,72,.14), transparent 26%),
60	linear-gradient(135deg,#f7f1e7 0%,#efe3cf 42%,#ead7bb 100%)}
61	.hero-grid,.cards,.route-grid,.sponsor-grid,.footer-cta,.proof-grid,.meta-grid,.fit-grid,.agenda-grid,.speaker-grid{display:grid;gap:24px}
62	.hero-grid{grid-template-columns:1.08fr .92fr;gap:48px;align-items:center}
63	.meta-grid{grid-template-columns:repeat(3,1fr);margin-top:34px}
64	.cards{grid-template-columns:repeat(3,1fr);margin-top:30px}
65	.fit-grid{grid-template-columns:repeat(4,1fr);margin-top:26px}
66	.proof-grid{grid-template-columns:1.05fr .95fr;align-items:start;margin-top:28px}
67	.route-grid{grid-template-columns:repeat(2,1fr);margin-top:30px}
68	.sponsor-grid{grid-template-columns:repeat(3,1fr);margin-top:30px}
69	.footer-cta{grid-template-columns:1fr 320px;align-items:center;gap:32px}
70	.chip{display:inline-flex;align-items:center;padding:10px 18px;border-radius:999px;border:1px solid var(--gold);background:rgba(255,255,255,.72);font-weight:800;color:#6b5134;box-shadow:0 4px 20px rgba(0,0,0,.03);backdrop-filter:blur(8px)}
71	.location-badge{display:inline-flex;align-items:center;gap:5px;margin-top:10px;font-size:14px;font-weight:900;color:var(--accent);letter-spacing:.04em}
72	.headline{font-size:clamp(42px,6vw,74px);line-height:.96;font-weight:900;margin:6px 0 10px;letter-spacing:-.03em}
73	.subheadline{font-size:clamp(23px,3vw,34px);color:var(--accent);font-weight:900}
74	.lead{font-size:clamp(18px,2vw,21px);color:#4e463f;margin-top:20px;max-width:760px}
75	.btn-row{display:flex;gap:14px;flex-wrap:wrap;margin-top:28px}
76	.btn{display:inline-flex;align-items:center;justify-content:center;padding:16px 28px;border-radius:999px;font-weight:900;transition:.22s ease;border:none;cursor:pointer;font-size:16px;font-family:inherit}
77	.btn:hover{transform:translateY(-2px)}
78	.btn-primary{background:#241f1a;color:#fff;box-shadow:0 14px 34px rgba(36,31,26,.14)}
79	.btn-secondary{border:1px solid var(--gold);background:rgba(255,255,255,.75);color:#6b5134}
80	.hero-box,.card,.price-box,.route-card,.signup-card,.qr-panel,.proof-card,.fit-card,.agenda-card,.speaker-card{background:var(--paper);border:1px solid #e4d4bf;border-radius:30px;box-shadow:var(--shadow)}
81	.hero-box{padding:30px;background:rgba(255,255,255,.86)}
82	.badge{display:inline-block;background:var(--accent);color:#fff;padding:6px 12px;border-radius:999px;font-weight:900;font-size:13px}
83	.hero-box h3{margin:14px 0 8px;font-size:clamp(32px,4vw,48px);line-height:1.1}
84	.hero-box p{margin:0;color:var(--muted);font-size:18px}
85	.countdown{display:flex;flex-wrap:wrap;align-items:center;gap:12px;background:#fff3e5;border:1px solid #e8cfa8;padding:14px 20px;border-radius:18px;margin-top:22px;font-weight:900;box-shadow:0 8px 20px rgba(167,123,60,.08)}
86	.count-live{display:inline-flex;align-items:center;gap:10px}
87	.count-timer{display:inline-flex;flex-wrap:wrap;gap:10px}
88	.time-box{min-width:72px;padding:10px 12px;border-radius:14px;background:#fff;border:1px solid #ecd7b7;text-align:center;box-shadow:0 6px 16px rgba(167,123,60,.06)}
89	.time-box strong{display:block;font-size:22px;line-height:1.1;color:#7a4c2b}
90	.time-box span{display:block;margin-top:4px;font-size:12px;color:#8b7257;font-weight:800;letter-spacing:.08em}
91	.count-dot{width:10px;height:10px;border-radius:999px;background:#c44d2b;box-shadow:0 0 0 8px rgba(196,77,43,.12)}
92	.meta-card,.fit-card{padding:20px}
93	.meta-card strong{display:block;margin-top:6px;font-size:28px;line-height:1.2}
94	h2{font-size:clamp(32px,4vw,52px);margin:0 0 14px;font-weight:900;line-height:1.12;letter-spacing:-.02em}
95	.section-lead{font-size:19px;color:var(--muted);max-width:860px}
96	.card{padding:26px;transition:.22s ease}
97	.card:hover{transform:translateY(-4px)}
98	.num{width:48px;height:48px;border-radius:999px;display:grid;place-items:center;background:#f1e2cf;color:#8a6844;font-weight:900}
99	.flow-sub{margin-top:18px;font-size:12px;font-weight:900;letter-spacing:.18em;text-transform:uppercase;color:#8a6844}
100	.flow-title{margin-top:8px;font-size:28px;font-weight:900;line-height:1.15}
101	.flow-text{margin-top:12px;color:var(--muted)}
102	.highlight{background:linear-gradient(135deg,var(--accent),var(--accent-2));color:#fff;padding:80px 0;text-align:center}
103	.highlight .eyebrow{color:#f8dfc6}.highlight h2{color:#fff}.highlight p{max-width:860px;margin:18px auto 0;color:#faeee7;font-size:20px}
104	.price-wrap{display:grid;grid-template-columns:1.05fr .95fr;gap:40px;align-items:start}
105	.price-box{padding:30px;background:linear-gradient(180deg,#fffaf2 0%,#f3e7d5 100%)}
106	.price{font-size:clamp(52px,7vw,78px);font-weight:900;line-height:1;margin:10px 0 4px}
107	.checklist{display:grid;gap:8px;color:#4e463f;margin-top:16px}
108	.route{background:#fffdf9;border-top:1px solid var(--line);border-bottom:1px solid var(--line)}
109	.route-card{padding:32px;background:#fff;transition:.25s ease;cursor:pointer}
110	.route-card:hover{transform:translateY(-6px);box-shadow:0 26px 60px rgba(0,0,0,.12)}
111	.entry-icon{width:200px;height:200px;border-radius:44px;background:linear-gradient(135deg,#ffffff,#f3e7d5);display:flex;flex-direction:column;align-items:center;justify-content:center;font-weight:900;border:1px solid #e2d2bd;box-shadow:0 14px 30px rgba(0,0,0,.08);transition:.25s;position:relative;overflow:hidden}
112	.entry-icon::after{content:"";position:absolute;inset:auto -28px -34px auto;width:110px;height:110px;border-radius:999px;background:rgba(200,132,91,.10);filter:blur(2px)}
113	.entry-emoji{display:flex;align-items:center;justify-content:center;gap:12px;font-size:70px;line-height:1}
114	.entry-emoji .accent-mark{font-size:44px;transform:translateY(-8px)}
115	.entry-emoji.team .accent-mark{font-size:42px;transform:none}
116	.route-card:hover .entry-icon{transform:scale(1.05)}
117	.entry-icon span{font-size:24px;margin-top:10px;font-weight:900;color:#5b5148;letter-spacing:.06em}
118	.route-note{margin-top:14px;padding:14px 16px;border-radius:18px;background:#f8f1e7;color:#6b5d50;font-size:14px}
119	.route-head{display:flex;justify-content:space-between;gap:18px;align-items:flex-start}
120	.qr-box{width:104px;height:104px;display:grid;place-items:center;text-align:center;border-radius:24px;border:1px solid #d8c6b1;background:linear-gradient(135deg,#fff 0%,#f4eadc 100%);font-size:12px;font-weight:800;color:#7a6857}
121	.sponsor{background:linear-gradient(180deg,var(--olive) 0%,var(--olive-2) 100%);color:#fff;padding:96px 0}
122	.sponsor .eyebrow{color:#d8c6b1}.sponsor .section-lead{color:#e8ddd0}
123	.sponsor-card{background:rgba(255,255,255,.06);padding:30px;border-radius:28px;border:1px solid rgba(255,255,255,.1);backdrop-filter:blur(10px)}
124	.sponsor-card h3{margin:0;color:#f5e7d8;font-size:24px}
125	.sponsor-card .plan-tag{display:inline-block;margin-top:8px;padding:6px 10px;border-radius:999px;background:rgba(255,255,255,.10);font-size:12px;font-weight:900;color:#dfc4aa}
126	.sponsor-card ul{margin:14px 0 0;padding-left:20px;color:#f6efe8}.sponsor-card li+li{margin-top:8px}
127	.sponsor-note{max-width:720px;margin:34px auto 0;text-align:center;color:#e8ddd0;font-size:15px;line-height:1.9}
128	.booth-photo{width:100%;aspect-ratio:1/1;border-radius:20px;overflow:hidden;margin-bottom:16px;border:1px solid rgba(255,255,255,.14)}
129	.booth-photo img{width:100%;height:100%;object-fit:cover}
130	.booth-photo.contain{background:rgba(255,255,255,.08)}
131	.booth-photo.contain img{object-fit:contain}
132	.booth-card .plan-tag{margin-top:0}
133	.booth-desc{margin:10px 0 0;color:#f6efe8;font-size:15px;line-height:1.8}
134	.donor-list{display:flex;flex-wrap:wrap;gap:12px;margin-top:20px;justify-content:center}
135	.donor-chip{background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.16);border-radius:14px;padding:12px 20px;color:#f6efe8;font-size:15px;font-weight:700;line-height:1.6}
136	.signup{padding:92px 0}
137	.signup-card{padding:40px;background:linear-gradient(135deg,#f8f1e7,#efe0c8)}
138	.link-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:16px;margin-top:28px}
139	.link-card{border-radius:22px;border:1px solid #ddcdb8;background:rgba(255,255,255,.75);padding:18px}
140	.link-value{margin-top:8px;word-break:break-all;font-weight:800}
141	.qr-panel{padding:24px;text-align:center;background:rgba(255,255,255,.88)}
142	.qr-real{width:224px;height:224px;margin:0 auto;border-radius:26px;background:linear-gradient(135deg,#ffffff 0%,#f4eadc 100%);border:1px solid #d8c6b1;display:grid;place-items:center;overflow:hidden}
143	.qr-real img{width:180px;height:180px}
144	.tiny-proof{margin-top:16px;font-size:12px;line-height:1.75;color:#8a7a6a}
145	.sticky{position:fixed;left:0;right:0;bottom:0;background:rgba(36,31,26,.94);backdrop-filter:blur(10px);padding:12px 16px;display:flex;justify-content:center;gap:12px;z-index:999;border-top:1px solid rgba(255,255,255,.08)}
146	.sticky a,.sticky button{background:#fff;padding:14px 22px;border-radius:999px;font-weight:900;color:#241f1a;min-width:150px;text-align:center;border:none;cursor:pointer;font-size:16px;font-family:inherit}
147	.sticky a.primary,.sticky button.primary{background:#f6d2b4}
148	.small-note{font-size:14px;color:var(--muted-2);margin-top:10px}
149	footer{padding:0 0 84px;color:#8a7a6a;text-align:center;font-size:13px}
150	
151	/* 議程 Agenda */
152	.agenda-grid{grid-template-columns:repeat(auto-fit,minmax(280px,1fr));margin-top:30px}
153	.agenda-card{padding:26px}
154	.agenda-card:hover{transform:translateY(-4px)}
155	.agenda-speaker{display:inline-block;margin-top:16px;padding:6px 14px;border-radius:999px;background:#f1e2cf;color:#6b5134;font-weight:900;font-size:14px}
156	.agenda-speaker.tbd{background:#efe6d8;color:#8a7a6a}
157	
158	/* 講師陣容 Speakers */
159	.speaker-grid{grid-template-columns:repeat(2,1fr);margin-top:30px}
160	.speaker-card{padding:22px;display:grid;grid-template-columns:132px 1fr;gap:18px;align-items:start}
161	.speaker-card:hover{transform:translateY(-4px)}
162	button.speaker-card{border:none;text-align:left;cursor:pointer;font-family:inherit;width:100%;transition:.22s ease}
163	.speaker-hint{margin-top:12px;display:inline-flex;padding:8px 16px;border-radius:999px;background:var(--accent);color:#fff;font-weight:900;font-size:13px}
164	.speaker-bio-modal .modal-box{max-width:560px}
165	.speaker-bio-modal .modal-body{padding:26px 28px 30px}
166	.speaker-bio-modal .modal-body p{margin:0;color:var(--muted);font-size:15px;line-height:1.85}
167	.speaker-photo{width:132px;aspect-ratio:1 / 1.2;border-radius:18px;background:linear-gradient(135deg,#f1e2cf,#e4d4bf);display:flex;align-items:center;justify-content:center;font-size:36px;font-weight:900;color:#8a6844;overflow:hidden;border:1px solid #e4d4bf}
168	.speaker-photo img{width:100%;height:100%;object-fit:cover;object-position:center top}
